// Package integration holds the build-time data of the integration overview (getIntegrationOverview, F059-2):
// the prefix → service groups of the APISIX route-as-code file, generated by tools/routegroups from
// deploy/apisix/routes/routes.yaml (`make gen`, checked by `make gen-check`) and embedded, so core-api never reads
// a deployment file at run time (OQ F059-12).
package integration

import (
	_ "embed"
	"encoding/json"
	"fmt"

	"github.com/tanguyen2020/eduworld-platform/src/backend/modules/identity/internal/application/query"
)

//go:embed route_groups.json
var routeGroups []byte

// RouteGroups returns the embedded route groups.
func RouteGroups() ([]query.RouteGroup, error) {
	var out []query.RouteGroup
	if err := json.Unmarshal(routeGroups, &out); err != nil {
		return nil, fmt.Errorf("integration: route groups: %w", err)
	}
	return out, nil
}
